   "question": "依次填入下列横线处的词语，最恰当一组是：\n在最困难的地方，往往______着巨大的创新契机。创新的灵感火花往往会在那些不便捷、不舒服、不顺手、不畅销的困境中_______，一个新领域或许就因此而生。生活中常见事物背后的创新故事就是对此的最好_______。例如，日常生活中常用的拉链，就是因为扣子太多扣起来费时而发明的。",
