   "module": "言语理解与表达",
   "source": "2016年吉林省公务员录用考试《行测》题（乙级） · 第15题",
   "question": "在发达国家，做慈善回馈社会是不二之选。最近扎克伯格裸捐450亿美元，就是对国内富豪的一次有益刺激。只有当“财富积累正当”的议程___________到“财富使用正当”，中国富豪的正名之路才算走到尾声。\n填入画横线部分最恰当的一项是：",
