   "question": "依次填入划横线部分最恰当的一组是：\n从家庭来说，现在父母大多为职场人士，难以         同子女沟通交往，就是在有限的交往中，也更在意孩子的学业，包括学习成绩和所谓“素质培养”，而很少                。",
