   "question": "依次填入划横线部分最恰当的一组是：\n语言系统其实具有自我           能力，随着时间推移，会自然通过分层过滤，淘尽渣滓，淬炼真金。虽然如此，当下部分网络语言带来的负面影响仍                。",
