   "source": "2018年421联考《行测》题（吉林乙级） · 第14题",
   "question": "依次填入划横线部分最恰当的一组是：\n尽力也许并不能让我们的未来              ，但是，         会让我们的明天          。因为，真的，人生很贵，请别浪费。",
