   "module": "言语理解与表达",
   "source": "2021年吉林省公务员录用考试《行测》题 · 第17题",
   "question": "为了进一步探索乌龙茶香气的酶促形成，团队成员系统研究了乌龙茶香气的酶促形成与胁迫的关联性。通过筛选各类胁迫因子，发现在乌龙茶加工过程中，损伤和低温胁迫是诱导茶叶香气酶促形成的关键胁迫因子。乌龙茶加工过程中做青阶段的连续损伤可诱导来自不同生物合成路径的香气物质合成关键基因的表达水平升高，进而促使这些香气物质的蓄积。此外，低温和损伤双胁迫对这些香气物质的合成具有显著协同效应。\n这段文字意在说明：",
   "options": [
    "A. 乌龙茶香气的酶促形成主要与胁迫相关",
    "B. 做青阶段连续损伤可诱导香气物质的蓄积",
    "C. 胁迫使香气物质合成关键基因表达水平升高",
    "D. 损伤和低温是香气酶促形成的关键胁迫因子"
   ],
   "answer": "A",
   "analysis": "文段开头指出团队成员系统研究了乌龙茶香气的酶促形成与胁迫的关联性以探索乌龙茶香气的酶促形成，接着介绍了研究发现的内容，指出在“损伤和低温胁迫是诱导茶叶香气酶促形成的关键胁迫因子”，然后指出“连续损伤可促使香气物质的蓄积”以及“低温和损伤双胁迫对这些香气物质的合成具有显著协同效应”，都在说明胁迫因子中的“损伤和低温威胁”对乌龙茶的香气物质形成有一定的作用，故文段是通过后文的研究来说明乌龙茶香气的酶促形成与胁迫有关，对应A项。\nB、C、D三项均为后文解释部分的内容，未包含文段主题词“乌龙茶”，排除。\n故正确答案为A。\n【文段出处】《研究发现中国乌龙茶香气酶促形成机制》",
