   "question": "①我国现存辽塔约有90座，其中辽宁省内就有约40座\n②辽宁辽塔的“辽”字，既有空间上的地理分布，又有时间上的历史积淀\n③辽代古塔简称辽塔，其以独特的风格造型和精美的建造艺术在中华古塔中独树一帜\n④一座座矗立在辽宁省内的辽塔，历经千年，记录着佛教在东北地区的传播流变，也成为我们窥探大辽王朝兴衰的一扇窗\n⑤契丹民族兴起于辽河河畔，辽宁省名源于辽河\n将以上5个句子重新排列，语序正确的是：",
   "options": [
    "A. ③①⑤②④",
    "B. ③⑤①②④",
    "C. ②③①④⑤",
    "D. ①③②⑤④"
   ],
   "answer": "A",
   "analysis": "对比选项，判断首句，①句指出我国现存辽塔的数量，②句指出辽塔中“辽”的内涵，③句引出辽塔这一话题。应先引出话题，再围绕其展开论述。故③句更适合作为首句，排除C、D两项。\n继续对比选项，寻找线索。A、B两项的区别在于③句之后接①句还是⑤句，①句围绕辽塔话题，指出现存数量，与③句话题一致，而⑤句强调辽宁省的名字来源，与③句话题不一致，故确定③①两句捆绑，锁定A项。\n故正确答案为A。\n【文段出处】《辽宁辽塔 占据全国辽塔半壁江山的古塔群》",
