   "answer": "C",
   "analysis": "第一空，根据“即”可知，体现解释“京味儿”的意思，C项“顾名思义”指从事物的名称联想到它的含义，符合文意，保留。A项“不言而喻”指不必说就能明白，D项“毋庸置疑”指事实明显或理由充分，根本就没有怀疑的余地，一般指某种观点的确定性，均无法体现解释之意，排除；B项“简而言之”指简括地说，长话短说，文段并非概括而是解释，与文意不符，排除。\n第二空，代入验证，C项“深入人心”指深深地进入到人们的心里，符合文意，当选。\n故正确答案为C。\n【文段出处】北京日报《把脉时代生活挖掘“新京味儿”》",
