   "question": "趣说古诗词，不是简单地用一些当代词汇对译古代生活场景，而是识得古人真趣，也就是认识体会他们活泼的创造力。不需要过于严肃地评点古人或褒奖古人，更不要希望用一个模式一个套路把古代好诗词“            ”，我们不应当以无趣的赏析套路把古典诗词掐死闷死，也不可能把古典诗人的“        ”都识破，留下活路，后人会有更新锐的解读。\n依次填入画横线处最恰当的一项是：",
