   "question": "盗蛛是一种捕鱼蛛，多生活在溪水面上，有的盗蛛经常将两只长脚伸进水里探测小鱼的动向，就好像“姜太公”钓鱼静待它们“            ”，当小鱼游进捕猎范围，盗蛛就会突然扑过去，并用两只长脚将小鱼紧紧抱住，将其拖入自己的洞穴。有的盗蛛还会用后面一对步足紧抓水面漂浮物，将其余几对伸出去，            ，一旦遇见合适的目标，便会迅速扑上去，先用口器咬住猎物，然后再将毒液注入其体内，使猎物中毒昏迷。\n依次填入画横线处最恰当的一项是：",
