   "source": "2023年吉林省公务员录用考试《行测》题 · 第18题",
   "question": "一箭多星是指一枚运载火箭同时或先后将多枚卫星送入预定轨道的技术。与传统的单星发射相比，一箭多星能够更充分地利用火箭运载能力，提高发射效率，降低发射成本。一箭多星发射技术难度较大，目前世界上只有少数国家掌握。2015年我国长征六号运载火箭在首飞任务中，成功将20颗卫星送入太空。2022年，我国长征八号运载火箭飞行试验取得圆满成功。此次任务共搭载22颗卫星，创下我国一箭多星任务最高纪录。\n关于一箭多星，文段没有提到的是：",
   "options": [
    "A. 基本含义",
    "B. 世界纪录",
    "C. 效率优势",
    "D. 中国实力"
   ],
   "answer": "B",
   "analysis": "A项，根据“一箭多星是指一枚运载火箭同时或先后将多枚卫星送入预定轨道的技术”可知，文段介绍了一箭多星的“基本含义”，表述正确，排除；\nB项，文段没有提到一箭多星的“世界纪录”，无中生有，当选；\nC项，根据“与传统的单星发射相比，一箭多星能够更充分地利用火箭运载能力，提高发射效率，降低发射成本”可知，文段介绍了一箭多星的“效率优势”，表述正确，排除；\nD项，根据“2022年，我国长征八号运载火箭飞行试验取得圆满成功。此次任务共搭载22颗卫星，创下我国一箭多星任务最高纪录”可知，文段介绍了一箭多星的“中国实力”，表述正确，排除。\n本题为选非题，故正确答案为B。\n【文段出处】人民日报《一箭发射22颗卫星，如何实现？》",
   "exam": "jilin",
