   "module": "言语理解与表达",
   "source": "2024年吉林省公务员录用考试《行测》题 · 第18题",
   "question": "下列俗语中，用法正确的一项是：",
   "options": [
    "A. 人外有人，天外有天。如果家长一味拿自己的孩子和该领域能力最强的孩子比，只会更加焦虑。但如果把孩子的现在和过去比，就会收获进步。",
    "B. 锅不热，饼不贴。如果心里没有人民群众，没有“俯首甘为孺子牛”的姿态，即使身体走进群众，内心也没有和群众在一处。",
    "C. 外行看热闹，内行看门道。《疯狂动物城》《狮子王》这类文化作品，不仅讲出了精彩的故事，而且也体现了生态价值。",
    "D. 煮饭要放米，讲话要讲理。蒙自米线味道如此鲜美，怎么能随便对付一口呢？就算再忙再累，蒙自人民也会为吃一锅热气腾腾的美味米线而精心熬制一锅高汤。"
   ],
   "answer": "B",
   "analysis": "A项：“人外有人，天外有天”的意思是高明的人上面还有更高明的人，就像我们看见的天之外还有更高的天一样，指厉害的人之上往往还有更厉害的人。通常用这句话来劝诫人不能自满自大，要不断学习和进步，认识到自己的知识和能力是有限的，总有比自己更强的人存在。而后文主要强调家长不要拿自己的孩子和该领域能力最强的孩子相比，并没有表达不能自满自大之意，故该俗语使用错误，排除。\nB项：“锅不热，饼不贴”的原意是如果锅不热，贴在锅上的饼子就会不牢固，容易滑落，比喻只有具备满腔热情，才能搞好团结。常用这个谚语来形容在党的群众路线教育实践活动中，领导和机关干部需要有一颗火热的心，自身具备一定“热度”才能拉近与群众的距离，提高基层服务的质量。与后文强调的心里要装着群众意思一致，故该俗语用法正确，当选。\nC项：“外行看热闹，内行看门道”的意思是懂行的专家可以看透本质，外行人只能看表面。此句通过比较说明内行与外行的区别，强调专业知识和经验的重要性，或说明某事另有玄机。而后文仅提及《疯狂动物城》《狮子王》这类文化作品的优点，故该俗语的用法错误，排除。\nD项：“煮饭要放米，讲话要讲理”的意思是就像锅里不下米就不能煮饭一样，说话不在理就不能使人信服。而后文仅表达出蒙自米线非常美味，并没有体现说话应讲理，故该俗语的用法错误，排除。\n故正确答案为B。",
   "exam": "jilin",
   "year": 2024,
