   "source": "2024年吉林省公务员录用考试《行测》题 · 第20题",
   "question": "水杉是起源于中生代白垩纪的珍贵濒危树种，生长在北纬35度以北的地区。在第四纪冰川时，水杉物种受到了巨大冰川的侵害。但幸运的是，部分水杉在中国被保存了下来，在鄂西南地区，现存有5700多棵水杉母树。\n以上是一篇文章的开头，接下来最有可能论述的是：",
   "options": [
    "A. 鄂西南的水杉为什么会幸存下来",
    "B. 鄂西南的水杉是何以保存的",
    "C. 鄂西南的水杉给旅游能带来哪些红利",
    "D. 鄂西南的水杉是怎么形成的"
   ],
   "answer": "A",
   "analysis": "本题为接语选择题，应通读全文，重点关注文段最后论述的核心话题。文段开篇介绍水杉为濒危树种，随后指出其在第四纪冰川时受到侵害，接着通过“但”进行转折，指出中国鄂西南地区现存5700多棵水杉母树。根据话题一致性与连贯性原则，后文应继续围绕鄂西南地区的水杉进行论述，介绍为何这一地区的水杉会幸存下来，对应A项。\nB项：“何以保存”为水杉的具体保存方法和策略，而文段中通过与前文所述水杉受到恶劣环境的侵害作对比，介绍水杉可以在中国鄂西南地区存活，“保存方法”与文段最后论述的核心话题不一致，衔接不当，排除。\nC、D两项：“给旅游能带来哪些红利”“水杉是怎么形成的”文段均未提及，无中生有，排除。\n故正确答案为A。\n【文段出处】人民日报《利川有棵“神奇树”》",
   "exam": "jilin",
   "year": 2024,
   "materialId": null
