   "source": "2024年吉林省公务员录用考试《行测》题 · 第21题",
   "question": "中国古代的词以一种轻松娱乐的方式流传于宋代都市的瓦舍勾栏之中，因其浮于表面、耽于俗艳，成为闺中艳词，体现俚俗化的特点。但因为文人士大夫的介入，他们将诗歌中的精致美感和壮阔气势融入词之中，不止赏心，而且悦心、悦神。于是便有了苏轼“大江东去，浪淘尽，千古风流人物”的豪迈气概，有了辛弃疾“白发空垂三千丈，一笑人间万事”的悲壮慷慨。词既体现了精致美感，也蕴含了人生态度，奠定了词的雅文学的历史地位。\n上述文段强调的是：",
   "options": [
    "A. 悦心与悦神的雅文学更值得推崇",
    "B. 词风由俗转变到雅",
    "C. 文人士大夫促进了词的风雅化",
    "D. 雅文学的历史地位由豪放派奠基"
   ],
   "answer": "C",
   "analysis": "文段开篇介绍“中国古代的词”具有俚俗化的特点，接着通过“但”进行转折，强调文人士大夫的介入使得词不止赏心，而且悦心、悦神，并以苏轼、辛弃疾的词句进行举例论证，尾句强调词由此奠定了雅文学的历史地位。故整个文段为“分—总”结构，重点强调文人士大夫的介入使得词由俚俗化转变为雅文学，对应C项。\nA项：缺少文段核心话题“文人士大夫”，且“更值得推崇”无中生有，排除。\nB、D两项：均缺少文段核心话题“文人士大夫”，排除。\n故正确答案为C。\n【文段出处】人民网《雅尚之美正当时》",
   "exam": "jilin",
   "year": 2024,
   "materialId": null
