   "source": "2024年吉林省公务员录用考试《行测》题 · 第23题",
   "question": "手语是主要运用于听障人士之间、聋听之间交流的视觉语言。与有声语言一样，手语也能够表达深刻的思想和丰富的情绪。与有声语言一样，手语也具备艺术表现形式。手语诗歌就是其中之一。手语诗歌也讲求韵律和谐、语言优美、富有节奏，手语诗歌的韵律可运用同样的手势，同一个位置，同一种运动来体现，具有对称性和平衡性。手语者可通过手语的手势、表情、姿势、空间和时间的变化来模拟生动的诗歌画面。运用手势，情绪和姿势将诗歌的意蕴在空间呈现出来。\n根据以上文段，作者重在表明，与有声语言相比：",
   "options": [
    "A. 手语也能深刻丰富地表情达意",
    "B. 手语可以将日常交流诗歌化表达",
    "C. 手语的语言表现力并不比有声语言逊色",
    "D. 手语对诗歌的表达同样具有艺术表达形式"
   ],
   "answer": "C",
   "analysis": "文段开篇通过下定义的方式引出 “手语”的话题，接着将手语与有声语言进行对比，指出手语也能表达深刻的和丰富的情绪，也具备艺术表现形式，并以手语诗歌为例详细解释说明。故文段为“分—总—分”结构，重在强调手语具有和有声语言一样的语言表现力，对应C项。\nA、D两项：均仅对应手语其中一方面的特点，表述片面，排除。\nB项： “手语可以将日常交流诗歌化表达” 文段并未提及，无中生有，排除。\n故正确答案为C。\n【文段出处】光明日报《【新闻随笔】手语传经典为何如此重要》",
   "exam": "jilin",
   "year": 2024,
   "materialId": null
