   "question": "穿山甲是独居动物，只有在交配季节才会彼此相遇。雄性个体不会主动去寻找雌性，而是留下气味标记，让雌性找到它。穿山甲通常在晚上行动，白天的时候它会缩成一团睡觉。每种穿山甲都有自己最爱的一到两种昆虫作为食物，它们非常挑食且口味独特！穿山甲性情温和，尖利的爪子除了挖洞没有任何杀伤力，它也不会主动去攻击其他物种。幼体穿山甲喜欢趴在妈妈的尾巴上，感觉到威胁它会把脸埋在尾巴下，直到威胁离开。\n下列选项说法正确的是：",
   "options": [
    "A. 穿山甲只有在白天的时候才出来活动",
    "B. 穿山甲只有在交配的季节才会共同生活",
    "C. 穿山甲的爪子和甲片具有防御功能",
    "D. 穿山甲对于食物的喜好具有个性化"
   ],
   "answer": "D",
   "analysis": "A项：根据“穿山甲通常在晚上行动，白天的时候它会缩成一团睡觉”可知，穿山甲只有在晚上的时候才出来活动，该项表述错误，排除。\nB项：根据“穿山甲是独居动物，只有在交配季节才会彼此相遇”可知，穿山甲只有在交配季节才会彼此相遇，“共同生活”偷换概念，排除。\nC项：“穿山甲的爪子和甲片具有防御功能”文段并未提及，无中生有，排除。\nD项：根据“每种穿山甲都有自己最爱的一到两种昆虫作为食物，它们非常挑食且口味独特”可知，穿山甲对于食物的喜好具有个性化，该项表述正确，当选。\n故正确答案为D。\n【文段出处】搜狐网《每周一物种：中华穿山甲》",
